import React, { useState, useEffect, useCallback, useMemo } from "react";
import { Box, Typography, Stack, CircularProgress } from "@mui/material";
import FitnessCenterIcon from "@mui/icons-material/FitnessCenter";
import CheckCircleOutlineIcon from "@mui/icons-material/CheckCircleOutline";
import PercentIcon from "@mui/icons-material/Percent";
import LocalFireDepartmentIcon from "@mui/icons-material/LocalFireDepartment";
import StatCard from "../../../components/Cards/StatCard";
import AreaGraph from "../../../components/Cards/AreaGraph";
import DataTable from "../../../components/DataTable";
import { useSelector } from "react-redux";
import { toast } from "react-hot-toast";
import dayjs from "dayjs";
import { apiGetJson } from "../../../utils/apiClient";

const WorkoutAnalytics = () => {
  const token = useSelector((state) => state.auth.token);
  const [data, setData] = useState(null);
  const [chartSeries, setChartSeries] = useState([]);
  const [chartYear, setChartYear] = useState(new Date().getFullYear());
  const [isLoading, setIsLoading] = useState(false);

  const fetchData = useCallback(async () => {
    if (!token) return;
    setIsLoading(true);
    try {
      const json = await apiGetJson("/analytics/workouts", token, { group: "month" });
      setData(json.data || null);
    } catch (err) {
      console.error("Error fetching workout analytics:", err);
      toast.error(err.message || "Failed to load workout analytics");
    } finally {
      setIsLoading(false);
    }
  }, [token]);

  const fetchSeries = useCallback(async () => {
    if (!token) return;
    try {
      const json = await apiGetJson("/analytics/workouts", token, {
        group: "month",
        start_date: `${chartYear}-01-01`,
        end_date: `${chartYear}-12-31`,
      });
      setChartSeries(json.data?.series || []);
    } catch (err) {
      console.error("Workout timeseries error:", err);
    }
  }, [token, chartYear]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  useEffect(() => {
    fetchSeries();
  }, [fetchSeries]);

  const summary = data?.summary || {};

  const chartData = useMemo(
    () =>
      (chartSeries || []).map((s) => ({
        month: s.period_start ? dayjs(s.period_start).format("MMM") : "-",
        value: s.count || 0,
      })),
    [chartSeries]
  );

  const topExerciseColumns = useMemo(
    () => [
      {
        id: "title",
        label: "Exercise",
        render: (row) => (
          <Typography sx={{ color: "#FFFFFF", fontSize: "0.85rem", fontWeight: 500 }}>
            {row.title}
          </Typography>
        ),
      },
      {
        id: "times_used",
        label: "Times Used",
        align: "right",
        render: (row) => (
          <Typography sx={{ color: "#4CC66E", fontSize: "0.85rem", fontWeight: 700 }}>
            {row.times_used}
          </Typography>
        ),
      },
    ],
    []
  );

  return (
    <Box sx={{ p: { xs: 2, md: 4 }, minHeight: "100vh", background: "linear-gradient(135deg, #0F0F10 0%, #1A1A1C 100%)" }}>
      <Stack sx={{ mb: 4 }}>
        <Typography variant="h4" sx={{ fontWeight: 800, color: "#fff", fontFamily: "'Montserrat', sans-serif", letterSpacing: "-0.04em", mb: 1 }}>
          Workout Analytics
        </Typography>
        <Typography variant="body2" sx={{ color: "rgba(255,255,255,0.4)", fontWeight: 500, fontFamily: "'Montserrat', sans-serif" }}>
          Training engagement, completion and most-used exercises.
        </Typography>
      </Stack>

      {isLoading ? (
        <Box sx={{ display: "flex", justifyContent: "center", py: 12 }}>
          <CircularProgress size={56} thickness={4} />
        </Box>
      ) : (
        <>
          <Box sx={{ display: "flex", flexDirection: { xs: "column", sm: "row" }, gap: { xs: 1.5, md: 3 }, mb: 3 }}>
            <StatCard title="Total Sessions" value={summary.total_sessions || 0} icon={<FitnessCenterIcon />} iconColor="#4CC66E" />
            <StatCard title="Completed Sessions" value={summary.completed_sessions || 0} icon={<CheckCircleOutlineIcon />} iconColor="#9F6EDA" />
            <StatCard title="Completion Rate" value={summary.completion_rate || 0} suffix="%" icon={<PercentIcon />} iconColor="#F5A623" subtitle={`${summary.completed_days || 0}/${summary.total_days || 0} days`} />
            <StatCard title="Avg Calories / Session" value={summary.avg_calories || 0} icon={<LocalFireDepartmentIcon />} iconColor="#FF5050" />
          </Box>

          <Box sx={{ mb: 3 }}>
            <AreaGraph title="Workout Sessions Over Time" data={chartData} lineColor="#4CC66E" selectedYear={chartYear} onYearChange={(yr) => setChartYear(yr)} />
          </Box>

          <DataTable
            title="Top Exercises"
            columns={topExerciseColumns}
            data={data?.top_exercises || []}
            isLoading={false}
            pagination={{ page: 0, rowsPerPage: 10, totalCount: (data?.top_exercises || []).length, onPageChange: () => {}, onRowsPerPageChange: () => {} }}
            emptyTitle="No exercise data"
            emptyMessage="No completed exercises in the selected period."
          />
        </>
      )}
    </Box>
  );
};

export default WorkoutAnalytics;
