import React, { memo } from "react";
import { Box, Typography } from "@mui/material";

/**
 * Lightweight metric tile (no trend) for analytics dashboards.
 */
const StatCard = ({
  title,
  value,
  prefix = "",
  suffix = "",
  icon,
  iconColor = "#4CC66E",
  subtitle,
}) => {
  const formattedValue =
    typeof value === "number"
      ? value >= 1000
        ? value.toLocaleString("en-US")
        : value % 1 !== 0
        ? value.toFixed(1)
        : value.toString()
      : value ?? "0";

  return (
    <Box
      sx={{
        flex: { xs: "none", sm: "1 1 0" },
        width: { xs: "100%", sm: "auto" },
        minWidth: 0,
        borderLeft: `6px solid ${iconColor}70`,
        boxSizing: "border-box",
        bgcolor: "#001e08ff",
        borderRadius: "16px",
        position: "relative",
        overflow: "hidden",
        p: "20px 24px",
        transition: "all 0.3s ease",
        "&:hover": { borderColor: iconColor, transform: "translateY(-4px)" },
      }}
    >
      {icon && (
        <Box sx={{ position: "absolute", top: 18, right: 18, color: iconColor, opacity: 0.8 }}>
          {React.cloneElement(icon, { sx: { fontSize: "1.3rem" } })}
        </Box>
      )}
      <Typography
        sx={{
          fontSize: "0.7rem",
          fontWeight: 700,
          color: "rgba(255,255,255,0.6)",
          textTransform: "uppercase",
          letterSpacing: "0.1em",
          mb: 1.5,
          pr: icon ? "32px" : 0,
          fontFamily: "'Montserrat', sans-serif",
        }}
      >
        {title}
      </Typography>
      <Typography
        sx={{
          fontSize: "2.1rem",
          fontWeight: 800,
          color: iconColor,
          fontFamily: "'Montserrat', sans-serif",
          lineHeight: 1,
          letterSpacing: "-0.02em",
        }}
      >
        {prefix}
        {formattedValue}
        {suffix}
      </Typography>
      {subtitle && (
        <Typography
          sx={{
            mt: 1,
            fontSize: "0.7rem",
            fontWeight: 600,
            color: "rgba(255,255,255,0.45)",
            fontFamily: "'Montserrat', sans-serif",
          }}
        >
          {subtitle}
        </Typography>
      )}
    </Box>
  );
};

export default memo(StatCard);
